sys_script_include.script:
var AIInsightService = Class.create();

AIInsightService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether an AI Insight record exists.
     *
     * @param {String} insightSysId
     * @return {Boolean}
     */
    insightExists: function(insightSysId) {

        if (this.validationUtils.isEmpty(insightSysId)) {
            return false;
        }

        var insight = new GlideRecord(
            'x_2130921_caresy_0_ai_insight'
        );

        if (!insight.isValid()) {
            gs.error(
                'AIInsightService: AI Insight table is invalid.'
            );
            return false;
        }

        return insight.get(insightSysId);
    },

    /**
     * Retrieve an AI Insight record.
     *
     * @param {String} insightSysId
     * @return {GlideRecord|null}
     */
    getInsight: function(insightSysId) {

        if (this.validationUtils.isEmpty(insightSysId)) {
            return null;
        }

        var insight = new GlideRecord(
            'x_2130921_caresy_0_ai_insight'
        );

        if (!insight.isValid()) {
            gs.error(
                'AIInsightService: AI Insight table is invalid.'
            );
            return null;
        }

        if (insight.get(insightSysId)) {
            return insight;
        }

        return null;
    },

    /**
     * Check whether an AI Insight record is active.
     *
     * @param {String} insightSysId
     * @return {Boolean}
     */
    isInsightActive: function(insightSysId) {

        var insight = this.getInsight(insightSysId);

        if (!insight) {
            return false;
        }

        return insight.getValue('active') == '1';
    },

    type: 'AIInsightService'
};
